-- Chomp Shop: schema generated by the DBA role (3NF)
-- Run: mysql -u root -p < database/schema.sql
DROP DATABASE IF EXISTS Chomp_shop;
CREATE DATABASE chomp_shop CHARACTER SET utf8mb4;
USE chomp_shop;

CREATE TABLE categories (
  category_id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(80) NOT NULL UNIQUE
);

CREATE TABLE products (
  product_id INT AUTO_INCREMENT PRIMARY KEY,
  category_id INT NOT NULL,
  sku VARCHAR(40) NOT NULL UNIQUE,
  name VARCHAR(120) NOT NULL,
  price DECIMAL(10,2) NOT NULL CHECK (price >= 0),
  stock INT NOT NULL DEFAULT 0 CHECK (stock >= 0),
  image_url VARCHAR(255) NULL,
  FOREIGN KEY (category_id) REFERENCES categories(category_id)
);

CREATE TABLE customers (
  customer_id INT AUTO_INCREMENT PRIMARY KEY,
  full_name VARCHAR(120) NOT NULL,
  email VARCHAR(150) NOT NULL UNIQUE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE orders (
  order_id INT AUTO_INCREMENT PRIMARY KEY,
  customer_id INT NOT NULL,
  status ENUM('pending','paid','shipped','cancelled') NOT NULL DEFAULT 'pending',
  order_date DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE order_items (
  item_id INT AUTO_INCREMENT PRIMARY KEY,
  order_id INT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL CHECK (quantity > 0),
  unit_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  UNIQUE (order_id, product_id),
  FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE demand_forecasts (
  forecast_id INT AUTO_INCREMENT PRIMARY KEY,
  product_id INT NOT NULL,
  forecast_date DATE NOT NULL,
  predicted_units INT NOT NULL,
  method VARCHAR(40) NOT NULL DEFAULT 'moving_avg_7d',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (product_id) REFERENCES products(product_id) ON DELETE CASCADE
);

CREATE TABLE price_audit (
  audit_id INT AUTO_INCREMENT PRIMARY KEY,
  product_id INT NOT NULL,
  old_price DECIMAL(10,2),
  new_price DECIMAL(10,2),
  changed_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Indexes for the most common lookups
CREATE INDEX idx_orders_date ON orders(order_date);
CREATE INDEX idx_forecast_product_date ON demand_forecasts(product_id, forecast_date);

-- VIEW: daily sales per product (feeds the forecasting procedure)
CREATE VIEW v_daily_sales AS
SELECT oi.product_id,
       DATE(o.order_date) AS sale_date,
       SUM(oi.quantity) AS units,
       SUM(oi.quantity * oi.unit_price) AS revenue
FROM order_items oi
JOIN orders o ON o.order_id = oi.order_id
WHERE o.status <> 'cancelled'
GROUP BY oi.product_id, DATE(o.order_date);

DELIMITER $$

-- TRIGGER: block overselling and snapshot the price
CREATE TRIGGER trg_order_items_before_insert
BEFORE INSERT ON order_items FOR EACH ROW
BEGIN
  DECLARE v_stock INT;
  DECLARE v_price DECIMAL(10,2);
  SELECT stock, price INTO v_stock, v_price FROM products WHERE product_id = NEW.product_id;
  IF v_stock < NEW.quantity THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Insufficient stock';
  END IF;
  IF NEW.unit_price = 0 THEN SET NEW.unit_price = v_price; END IF;
END$$

-- TRIGGER: deduct stock after an item is added
CREATE TRIGGER trg_order_items_after_insert
AFTER INSERT ON order_items FOR EACH ROW
BEGIN
  UPDATE products SET stock = stock - NEW.quantity WHERE product_id = NEW.product_id;
END$$

-- TRIGGER: audit every price change
CREATE TRIGGER trg_products_price_audit
AFTER UPDATE ON products FOR EACH ROW
BEGIN
  IF OLD.price <> NEW.price THEN
    INSERT INTO price_audit(product_id, old_price, new_price)
    VALUES (OLD.product_id, OLD.price, NEW.price);
  END IF;
END$$

-- STORED PROCEDURE: 7-day moving-average demand forecast
CREATE PROCEDURE sp_generate_forecast(IN p_product INT, IN p_days INT)
BEGIN
  DECLARE v_avg DECIMAL(10,2);
  DECLARE i INT DEFAULT 1;
  SELECT COALESCE(SUM(units), 0) / 7 INTO v_avg
  FROM v_daily_sales
  WHERE product_id = p_product AND sale_date >= CURDATE() - INTERVAL 7 DAY;
  WHILE i <= p_days DO
    INSERT INTO demand_forecasts(product_id, forecast_date, predicted_units)
    VALUES (p_product, CURDATE() + INTERVAL i DAY, ROUND(v_avg));
    SET i = i + 1;
  END WHILE;
END$$

DELIMITER ;

